import{_ as r,C as a,o as i,c,j as t,a as o,E as d,ag as l}from"./chunks/framework.HG0H2VLS.js";const y=JSON.parse('{"title":"SeatingToast","description":"","frontmatter":{},"headers":[],"relativePath":"components/seating-toast.md","filePath":"components/seating-toast.md"}'),h={name:"components/seating-toast.md"},g={id:"seatingtoast",tabindex:"-1"};function p(u,e,m,b,f,w){const s=a("Badge"),n=a("ComponentDemo");return i(),c("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-seatingtoast",tabindex:"-1"},[o("title: SeatingToast "),t("a",{class:"header-anchor",href:"#title-seatingtoast","aria-label":'Permalink to "title: SeatingToast"'},"​")],-1)),t("h1",g,[e[0]||(e[0]=o("SeatingToast ",-1)),d(s,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#seatingtoast","aria-label":'Permalink to "SeatingToast <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,[o("Seating Planner action confirmation / warning "),t("strong",null,"pill"),o(" with an Undo")])],-1)),d(n,{src:"/demos/src/components/SeatingToast/SeatingToast.html"}),e[6]||(e[6]=l('<h2 id="this-is-not-the-toast-component" tabindex="-1">This is NOT the <code>Toast</code> component <a class="header-anchor" href="#this-is-not-the-toast-component" aria-label="Permalink to &quot;This is NOT the `Toast` component&quot;">​</a></h2><p><code>src/components/Toast/</code> already exists — the general-purpose notification set (<code>2856:3020</code>, 10 variants). <strong>Figma names this one just &quot;Toast&quot; too</strong>, which is the first thing worth fixing: renaming it <code>Seating Toast</code> would stop two different components sharing a name in the property panel and in Code Connect.</p><p>They are genuinely different components, not two takes on one:</p><table tabindex="0"><thead><tr><th></th><th><code>Toast</code> (existing)</th><th><code>SeatingToast</code> (this)</th></tr></thead><tbody><tr><td>shape</td><td>card, <code>--ai-radius-lg</code> (16)</td><td><strong>pill, <code>--ai-radius-full</code></strong> (100)</td></tr><tr><td>width</td><td><code>--ai-size-7</code> (384)</td><td>465 drawn → <code>--ai-size-8</code> (448)</td></tr><tr><td>ground</td><td>white, or status-tinted on <code>--color</code></td><td><strong>always white</strong></td></tr><tr><td>border</td><td><code>--ai-border-secondary</code></td><td><strong>status colour</strong> (<code>success</code> / <code>error</code>)</td></tr><tr><td>icon</td><td>32px chip with a soft tinted background</td><td><strong>bare 20px glyph, no chip</strong></td></tr><tr><td>trailing</td><td>close button (always)</td><td><strong>Undo CTA (optional), no close</strong></td></tr><tr><td>variants</td><td>10 (4 statuses × plain/filled + 2 layouts)</td><td>2 (Success / Error)</td></tr><tr><td>dismissal</td><td><code>Toast.js</code> removes it on close click</td><td><strong>none — the caller owns it</strong></td></tr></tbody></table><p>So a status-bordered white pill with an Undo is not reachable from <code>Toast</code>&#39;s existing axes, and a separate component is right. Worth a designer decision at some point whether the system <em>wants</em> two notification components, or whether this should eventually become a <code>Toast</code> layout type alongside <code>--notification</code> and <code>--interactive</code>.</p><h2 id="variant-matrix-2-variants" tabindex="-1">Variant matrix (2 variants) <a class="header-anchor" href="#variant-matrix-2-variants" aria-label="Permalink to &quot;Variant matrix (2 variants)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Tier</th><th>Node</th><th>Figma size</th><th>CSS</th></tr></thead><tbody><tr><td>Success</td><td>Component</td><td><code>3474:90239</code></td><td>465×58</td><td><code>.seating-toast--success</code></td></tr><tr><td>Error</td><td>Component</td><td><code>3474:90238</code></td><td>465×58</td><td><code>.seating-toast--error</code></td></tr></tbody></table><p><code>Tier</code> is single-valued (<code>Component</code>). <strong>There is no Device axis</strong> — no mobile variant, and &quot;mobile&quot; appears nowhere in the set&#39;s design context or variables, so there is no media query. <code>max-inline-size: 100%</code> is what makes it safe on a narrow screen.</p><h3 id="type-changes-two-properties-not-the-whole-surface" tabindex="-1">Type changes two properties, not the whole surface <a class="header-anchor" href="#type-changes-two-properties-not-the-whole-surface" aria-label="Permalink to &quot;Type changes two properties, not the whole surface&quot;">​</a></h3><p>Type sets the <strong>border colour</strong> and the <strong>icon colour</strong>. The ground stays white in both — which is precisely what separates this from the <code>Toast</code> card&#39;s <code>--color</code> variants, where the status tints the whole card. Everything else (layout, padding, radius, shadow, typography, CTA) is identical between the two, so each modifier is two declarations.</p><h3 id="show-cta-is-a-real-boolean-property" tabindex="-1"><code>Show Cta</code> is a real boolean property <a class="header-anchor" href="#show-cta-is-a-real-boolean-property" aria-label="Permalink to &quot;`Show Cta` is a real boolean property&quot;">​</a></h3><p>The Figma component exposes <code>showCta</code> alongside the text props. Both <em>drawn</em> variants have the CTA, so <strong>Figma never shows what <code>Show Cta = false</code> looks like</strong> — the height there is emergent rather than specified: the pill drops to <strong>46px</strong>, because the CTA is what makes it tall. Built that way (no modifier needed — the flex row closes up on its own), but <strong>worth confirming</strong>: a toast that changes height depending on whether it offers an Undo may or may not be wanted.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code></td><td><code>background-color</code></td><td>rebound from <code>--ai-datatable-table-bg</code> — see below</td></tr><tr><td><code>--ai-border-success</code> / <code>--ai-border-error</code></td><td><code>border-color</code> per Type</td><td></td></tr><tr><td><code>--ai-border-secondary</code></td><td>base <code>border-color</code></td><td>neutral fallback; Figma defines no untyped state</td></tr><tr><td><code>--ai-radius-full</code></td><td><code>border-radius</code> (100px)</td><td>unbound in Figma as a raw <code>100px</code></td></tr><tr><td><code>--ai-shadow-md</code></td><td><code>box-shadow</code></td><td>see below</td></tr><tr><td><code>--ai-spacing-5</code></td><td><code>padding-inline</code> (16)</td><td>Figma reads 17 — see below</td></tr><tr><td><code>--ai-spacing-4</code></td><td><code>padding-block</code> (12), <code>gap</code> (12)</td><td>gap unbound in Figma as a raw <code>12px</code></td></tr><tr><td><code>--ai-spacing-3</code> / <code>--ai-spacing-4</code></td><td>CTA <code>padding</code> (8 / 12)</td><td>contextual override — see below</td></tr><tr><td><code>--ai-size-8</code></td><td><code>inline-size</code> (448)</td><td>Figma draws 465 — see below</td></tr><tr><td><code>--ai-icon-size-md</code></td><td>icon (20px)</td><td></td></tr><tr><td><code>--ai-surface-success</code> / <code>--ai-surface-error</code></td><td>icon <code>color</code></td><td>a SURFACE token on an icon — see below</td></tr><tr><td><code>--ai-font-body</code></td><td>message <code>font-family</code></td><td>note the <code>Toast</code> card uses <code>--ai-font-title</code></td></tr><tr><td><code>--ai-font-fixed-xs</code></td><td>message (14px)</td><td>unbound in Figma</td></tr><tr><td><code>--ai-leading-sm</code></td><td>message (20px)</td><td>unbound in Figma</td></tr><tr><td><code>--ai-font-regular</code> / <code>--ai-font-semibold</code></td><td>message / its <code>&lt;strong&gt;</code> spans</td><td></td></tr><tr><td><code>--ai-text-primary</code></td><td>message colour</td><td></td></tr></tbody></table><h3 id="the-padding-is-16-12-plus-the-border-not-17-13" tabindex="-1">The padding is 16/12 plus the border, not 17/13 <a class="header-anchor" href="#the-padding-is-16-12-plus-the-border-not-17-13" aria-label="Permalink to &quot;The padding is 16/12 plus the border, not 17/13&quot;">​</a></h3><p>Figma reads <code>px-[17px] py-[13px]</code>, neither of which is a token. They are <code>--ai-spacing-5</code> (16) and <code>--ai-spacing-4</code> (12) <strong>plus the 1px stroke</strong>: Figma measures its padding from outside a stroke it draws inside the box, where CSS adds the border on top of the padding. The arithmetic confirms it — <code>1 + 12 + 32 + 12 + 1 = 58</code>, exactly the height Figma states. So the tokens are 16/12 and nothing is off-scale.</p><h3 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h3><p>All resolved with the designer 2026-08-26 rather than invented.</p><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td>Unbound two-layer shadow: <code>0 0 10px rgba(0,0,0,.05)</code> + <code>0 2px 1px rgba(0,0,0,.1)</code>. The first layer is <strong>exactly <code>--ai-shadow-card</code></strong>; the second matches no layer of any token in the scale.</td><td><strong><code>--ai-shadow-md</code></strong> — the token the <code>Toast</code> card already uses, so the two notification surfaces cast the same shadow. Deliberately heavier than Figma draws here; a consistency call over a literal match. The alternative was <code>--ai-shadow-card</code> alone, which would have matched the dominant layer exactly.</td></tr><tr><td><code>bg</code> binds <strong><code>--ai-datatable-table-bg</code></strong> (#ffffff) — a Datatables token doing a surface&#39;s job on a toast</td><td><strong><code>--ai-surface-primary</code></strong>. Identical value today, but a toast should not change colour if the table background is ever retuned for a Datatables redesign. <strong>Worth rebinding in Figma.</strong></td></tr><tr><td><code>w-[465px]</code>, unbound and matching no <code>--ai-size-*</code> (size-8 is 448, size-9 is 512)</td><td><strong><code>--ai-size-8</code></strong> (448) plus <code>max-inline-size: 100%</code> — the same shape of rule the <code>Toast</code> card uses. A toast is a fixed-size floating element, so unlike TableCard or TableListing it is deliberately <strong>not</strong> fluid. 17px narrower than drawn.</td></tr><tr><td><code>rounded-[100px]</code>, <code>gap-[12px]</code>, message <code>14px</code> / <code>20px</code> — all unbound</td><td><strong><code>--ai-radius-full</code></strong>, <strong><code>--ai-spacing-4</code></strong>, <strong><code>--ai-font-fixed-xs</code></strong>, <strong><code>--ai-leading-sm</code></strong> — each matches its token exactly, so binding them is visually a no-op. <strong>All four worth binding in Figma.</strong></td></tr><tr><td>Icon coloured <code>--ai-surface-success</code> / <code>--ai-surface-error</code></td><td><strong>Used as drawn.</strong> A <em>surface</em> token doing an icon&#39;s job, because <strong>the icon scale has no success or error entry</strong> — it stops at primary / secondary / contrast / invert / invert-secondary / brand. Identical finding to Unassigned&#39;s empty-state tick; <code>--ai-icon-success</code> and <code>--ai-icon-error</code> are genuine holes worth filling.</td></tr></tbody></table><h2 id="the-cta-is-a-contextual-override-case-b" tabindex="-1">The CTA is a contextual override (Case B) <a class="header-anchor" href="#the-cta-is-a-contextual-override-case-b" aria-label="Permalink to &quot;The CTA is a contextual override (Case B)&quot;">​</a></h2><p>The <code>Undo</code> instance measures <strong>55×32</strong>. That does not match our <code>btn--xs</code>, and the interesting part is <em>why</em>.</p><p><code>get_variable_defs</code> on the instance (<code>3474:90189</code>) returns <code>--ai-spacing-1</code> (gap), <code>--ai-spacing-3</code>, <code>--ai-spacing-4</code>, <code>--ai-radius-sm</code>, <code>--ai-font-fluid-xxs</code>, <code>--ai-font-medium</code>, <code>--ai-leading-xs</code> and the <code>btn-secondary-*</code> family. Every one of those matches <code>.btn--xs</code><strong>except the padding</strong> — ours is <code>--ai-spacing-2 --ai-spacing-3</code> (6/8), the instance&#39;s is <code>--ai-spacing-3 --ai-spacing-4</code> (8/12).</p><p><strong>Checked against Button&#39;s own set (<code>53:2489</code>) rather than guessed:</strong> every <code>Size=xs</code> text variant there is <strong>115×28</strong> — Primary, Secondary, Tertiary and Alert alike. So Figma&#39;s Button component really is the tighter padding, <code>.btn--xs</code> is correct against its own source, and this instance is overriding it. <strong>Case B</strong>: scoped to <code>.seating-toast__cta.btn</code> and Button left untouched.</p><p>That matters because <code>btn--xs</code> has real consumers — ActionCard (2) and ControlHub (6). Treating this as Case A would have made all eight 4px taller and 8px wider to match one toast.</p><p>Two classes (<code>.seating-toast__cta.btn</code>) so the override wins on specificity rather than on stylesheet order.</p><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><ul><li><strong>Presentational only, no JS.</strong> Unlike <code>Toast</code>, there is no close button to wire, and the component deliberately owns neither its own appearance/disappearance nor an auto-dismiss timer — a toast is spawned and retired by whatever raised it.</li><li><strong><code>Undo</code> is a real <code>&lt;button&gt;</code></strong> but is not wired. It must reverse the <em>specific</em> operation that raised the toast, which means it needs that operation&#39;s id — see the handover note.</li><li><strong><code>role=&quot;status&quot;</code> on Success, <code>role=&quot;alert&quot;</code> on Error</strong>, following the convention the existing <code>Toast</code> component already set (<code>status</code> for info/success, <code>alert</code> for danger/warning). Success is announced politely; an error interrupts. This is what makes a toast usable at all — a visual-only toast is invisible to a screen-reader user.</li><li>The icon is <code>aria-hidden</code>, since the message already carries the meaning.</li><li><code>&lt;strong&gt;</code> carries Figma&#39;s semibold emphasis, so the emphasis is in the markup rather than purely visual.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Measured in headless Chrome at 1200px.</p><table tabindex="0"><thead><tr><th></th><th>Figma</th><th>Rendered</th><th></th></tr></thead><tbody><tr><td>pill</td><td>465×58</td><td><strong>448×60</strong></td><td>width by decision; +2px height — see below</td></tr><tr><td>radius</td><td>100px</td><td><strong>100px</strong></td><td>exact</td></tr><tr><td>border</td><td>1px <code>--ai-border-success</code> / <code>-error</code></td><td><strong>1px #adddc0 / #fdbdbe</strong></td><td>exact</td></tr><tr><td>padding</td><td>17 / 13</td><td><strong>16 / 12</strong> + 1px border</td><td>exact once the stroke is accounted for</td></tr><tr><td>gap</td><td>12</td><td><strong>12</strong></td><td>exact</td></tr><tr><td>icon</td><td>20×20, success / error</td><td><strong>20×20, #30a46c / #e5484d</strong></td><td>exact</td></tr><tr><td>message</td><td>14px / 20px, regular, semibold spans</td><td><strong>14 / 20, 400, 600</strong></td><td>exact</td></tr><tr><td>CTA</td><td>55×32</td><td><strong>56.8×34</strong></td><td>see below</td></tr><tr><td><code>Show Cta = false</code></td><td>not drawn</td><td>448×<strong>46</strong></td><td>emergent</td></tr><tr><td>long message</td><td>not drawn</td><td>wraps to 3 lines, pill grows</td><td></td></tr><tr><td>in a 320px container</td><td>not drawn</td><td><strong>294px, no overflow</strong></td><td><code>max-inline-size: 100%</code> holds</td></tr></tbody></table><p><strong>The +2px on both the pill and the CTA is one cause.</strong> The CTA renders 34 rather than 32 because <code>btn--secondary</code> carries a 1px border that CSS adds on top of the approved 8px padding, where Figma draws its stroke inside the 32. The pill is sized by its tallest child, so it inherits those 2px: <code>1 + 12 + 34 + 12 + 1 = 60</code>. Contorting the padding to 7px would fix the number and break the token rule, so it is left as border arithmetic — the same class of 1–3px difference already documented on Unassigned (296/480 vs 297/472) and SeatingHeader (291 vs 288).</p><p>Also verified: all icons resolve (zero unconverted <code>&lt;i&gt;</code>), the <code>seating-toast__icon</code> class survives <code>createIcons()</code> onto the generated <code>&lt;svg&gt;</code>, and roles alternate <code>status</code> / <code>alert</code> correctly across all six demo instances.</p><h2 id="notes-and-things-to-raise" tabindex="-1">Notes and things to raise <a class="header-anchor" href="#notes-and-things-to-raise" aria-label="Permalink to &quot;Notes and things to raise&quot;">​</a></h2><ul><li><strong>Both components are called &quot;Toast&quot; in Figma.</strong> Renaming this one is the single most useful fix.</li><li><strong>A pre-existing 2px in <code>btn--xs</code>, unrelated to this build.</strong> Figma draws its xs text button at 28; ours renders 30 (<code>6 + 16 + 6</code> plus a 1px border top and bottom) for the same stroke-inside-vs-added reason. Not touched here — it affects Button, ActionCard and ControlHub, and is a Button-level decision.</li><li><strong>The message&#39;s font family is <code>--ai-font-body</code></strong> here but <code>--ai-font-title</code> on the <code>Toast</code> card. One of the two is drift; worth a designer glance. Built as Figma binds it.</li><li><strong>Figma&#39;s text layer names are stale.</strong> The Success paragraph&#39;s layer is named <em>&quot;Placing Dame Helen Verity — choose a seat, a table&quot;</em> while its actual content reads <em>&quot;Helen Verity successfully assigned to Seat 2&quot;</em>. The content was taken from the design context, not the layer name.</li><li><strong>The message is <code>whitespace-nowrap</code> in Figma</strong>, which only holds for its sample strings. Left to wrap, since attendee and table names are not length-bounded and a nowrap pill would overflow rather than grow.</li><li><strong>Design context splits the message into per-character spans</strong> — a Figma artefact of mixed-style text. The parent <code>&lt;p&gt;</code> also carries <code>text-[0px]</code> and <code>--ai-text-secondary</code>, both meaningless (mixed runs collapse the parent&#39;s own values); the real values live on the spans, where the colour is a raw <code>#172033</code> that happens to equal <code>--ai-text-primary</code>.</li><li><strong>Code Connect emits no size class</strong> for the CTA (<code>btn btn--secondary</code> with a double space), the same gap seen on SeatingHeader&#39;s swap and global buttons. The size was resolved from geometry and bound variables instead.</li><li><strong>No hover, focus, pressed or disabled variants</strong> for the pill itself, and <strong>no dark-mode variant</strong>. The status border and icon colours are not theme-aware.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=3474-90240" target="_blank" rel="noreferrer">Open in Figma</a></p>',36))])}const T=r(h,[["render",p]]);export{y as __pageData,T as default};
